use super::*;
use super::super::KmoRowInfo::review::{row,clear};
use crate::cn::wps::moss::{app::{KmoBook::KmoBook,KmoBookApi::KmoBookApi,xf::{KmoXFManager::KmoXFManager,KmoXF::KmoXF,KmoFont::KmoFont}},util::KmoRect::KmoRect};
use serde_json::{Value,json};use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");json!({"result":s.split(':').next().unwrap()})}}}
fn xf(f:Option<&KmoXF>)->Value{f.map_or(Value::Null,|f|json!({"font":f.getFontIndex(),"format":f.getFormatIndex(),"numFormat":f.getNumFormat(),"fontName":f.getFont().map(|f|f.getFontName()),"locked":f.isLocked(),"wrap":f.getWrapText()}))}
fn manager(h:&Value,book:&KmoBook)->Value{let m=KmoXFManager::KmoXFManager();let mut xs:Vec<Rc<KmoXF>>=vec![];let mut out=vec![];for a in h["ops"].as_array().unwrap(){let mut f=None;let c=call(||{if a["null"]==true{return m.checkXFIndex(None);}let x=if let Some(n)=a["reuse"].as_u64(){xs[n as usize].clone()}else{let source=book.getXFManager().borrow().getXF(a["source"].as_i64().unwrap_or(15)as i32);let x=Rc::new(KmoXF::createXF(source.as_deref()));if a.get("numFormat").is_some(){x.setNumFormat(a["numFormat"].as_str().map(str::to_owned));}if let Some(name)=a["fontName"].as_str(){let old=book.getXFManager().borrow().getFont(0);let font=Rc::new(KmoFont::createFont(&old));font.setFontName(name.to_owned());x.setFont(font);}else if a["clearFont"]==true{x.setFont__nullable(None);}xs.push(x.clone());x};f=Some(x.clone());m.checkXFIndex(Some(x))});out.push(json!({"call":c,"xf":xf(f.as_deref()),"count":m.getNumExFormats(),"fonts":m.getNumFonts(),"formats":m.getAllNumfmts().len()}));}json!({"rows":out})}
fn clear_rows(s:&KmoSheet){let mut i=s.getRowInfos().iterator();while i.hasNext(){i.next();i.remove();}clear(s);}
fn pairs(mut it:super::super::KmoRowRange::KmoRowRangeIterator)->Value{let mut out=vec![];while it.hasNext(){let p=it.next();out.push(json!([p.first,p.second]));}json!(out)}
fn sheet(s:&KmoSheet)->Value{let mut rows=vec![];let mut it=s.getRowInfos().iterator();while it.hasNext(){let r=it.next().expect("NullPointerException");rows.push(json!({"at":it.index(),"row":row(&r),"xf":xf(s.getRowXF(it.index()).as_deref())}));}let queries:Vec<_>=[0,1,5,8,33,1050].into_iter().map(|n|json!([s.getHiddenRowsManager().isHidden(n),s.getHiddenRowsManager().getHiddenRowsCount(n),s.getOptHiddenRowColManager().isRowOperable(n),s.getOptHiddenRowColManager().isColOperable(n)])).collect();json!({"rows":rows,"first":s.getRowInfos().getFirstRow(),"last":s.getRowInfos().getLastRow(),"hidden":pairs(s.getHiddenRowsManager().iterator()),"operable":pairs(s.getOptHiddenRowColManager().rowIterator()),"queries":queries,"xfs":s.getBook().getXFManager().borrow().getNumExFormats(),"fonts":s.getBook().getXFManager().borrow().getNumFonts()})}
fn open()->Rc<KmoBookApi>{let api=KmoBookApi::KmoBookApi();let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));api}
fn merge(src:&KmoBook,p:&Value)->Value{let api=open();let dst=api.book();let from=src.getActiveSheet();let to=dst.getActiveSheet();clear_rows(&from.borrow());clear_rows(&to.borrow());let old=src.getXFManager().borrow().getXF(15);let custom=Rc::new(KmoXF::createXF(old.as_deref()));custom.setNumFormat(Some("0.0000\" merge\"".into()));let index=src.getXFManager().borrow().checkXFIndex(Some(custom));for n in [1,8,33,1050]{let r=Rc::new(KmoRowInfo::KmoRowInfo(n,(300+n)as i16,(index|12288)as i16,if n==8{288}else{384}));r.setMaxHeightCell(n+7);r.setMinHeightCell(n-3);from.borrow().getRowInfos().setRowInfo(Some(r));}to.borrow().getRowInfos().setRowInfo(Some(Rc::new(KmoRowInfo::KmoRowInfo(5,600,15,288))));let mut out=json!({"before":sheet(&to.borrow())});let range=KmoRect::KmoRect__bounds(0,0,p["bottom"].as_i64().unwrap_or(1050)as i32,10);let c=call(||{let offset=p["offset"].as_i64().unwrap_or(0)as i32;let ignore=p["ignore"].as_i64().unwrap_or(0)as i32;let range=if p["nullRange"]==true{None}else{Some(&range)};let from=from.borrow();let to=to.borrow();let book=if p["nullBook"]==true{None}else{Some(dst.as_ref())};match p["mode"].as_str().unwrap(){"all"=>to.getRowInfos().mergeCopy(Some(&from),book),"range"=>to.getRowInfos().mergeCopy__range(offset,ignore,range,Some(&from),Some(&dst)),"hidden"=>to.getHiddenRowsManager().mergeCopy(Some(&from)),"hiddenRange"=>to.getHiddenRowsManager().mergeCopy__range(offset,ignore,range,Some(&from)),"row"=>{let r=from.getRowInfos().getRowInfo(p["row"].as_i64().unwrap_or(8)as i32).expect("NullPointerException");let from=if p["nullSheet"]==true{None}else{Some(&*from)};let copied=if p["shortOverload"]==true{r.mergeCopy(from,book)}else{r.mergeCopy__row(p["newRow"].as_i64().unwrap()as i32,from,book)};return row(&copied);},_=>unreachable!()}Value::Null});out["call"]=c;out["after"]=sheet(&to.borrow());out["source"]=sheet(&from.borrow());out}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_row_merge_and_xf_manager_deduplication(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/row-merge-r0b71");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=open();let book=api.book();let managers:Vec<_>=input["managers"].as_array().unwrap().iter().map(|h|manager(h,&book)).collect();let merges:Vec<_>=input["merges"].as_array().unwrap().iter().map(|h|merge(&book,h)).collect();let actual=json!({"managers":managers,"merges":merges});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
